WITH unpacked AS (SELECT id, service, log_ts, status_code, payload_json, CAST((status_code & 1) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs) SELECT id, log_ts, status_code_high, COUNT(status_code) OVER w_part status_code_count_2h, NTILE(5) OVER (PARTITION BY service ORDER BY has_fault, id) has_fault_bucket FROM unpacked WHERE status_code >= 308 WINDOW w_part AS (PARTITION BY service ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW);
